<script setup lang="ts">
import { nextTick,ref,watch } from 'vue';
import { LoaderCircle, Package } from '@lucide/vue';
import { useI18n } from '../i18n';
import { componentPrompt,componentInstalling,componentError,cancelComponents,installComponents } from '../composables/useComponentPrerequisites';
const { t }=useI18n();const panel=ref<HTMLElement|null>(null);let previous:HTMLElement|null=null;
watch(componentPrompt,async value=>{if(value){previous=document.activeElement instanceof HTMLElement?document.activeElement:null;await nextTick();panel.value?.focus();}else previous?.focus();});
function keydown(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();cancelComponents();}if(e.key!=='Tab')return;const nodes=panel.value?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)');if(!nodes?.length){e.preventDefault();return;}const first=nodes[0]!,last=nodes[nodes.length-1]!;if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
</script>
<template><Teleport to="body"><div v-if="componentPrompt" class="component-mask" @keydown="keydown"><section ref="panel" class="component-panel" role="dialog" aria-modal="true" aria-labelledby="component-title" aria-describedby="component-body" tabindex="-1"><h2 id="component-title"><Package :size="21" />{{t('components.requiredTitle')}}</h2><p id="component-body">{{t('components.requiredBody')}}</p><p v-if="componentError" role="alert">{{componentError}}</p><p v-if="componentInstalling" role="status"><LoaderCircle :size="16" class="spin" />{{t('components.installing')}}</p><footer><button :disabled="componentInstalling" @click="cancelComponents">{{t('components.cancel')}}</button><button :disabled="componentInstalling" @click="installComponents">{{t('components.installContinue')}}</button></footer></section></div></Teleport></template>
<style scoped>.component-mask{position:fixed;inset:0;z-index:1190;display:grid;place-items:center;background:rgb(0 0 0 / .34);padding:20px;}.component-panel{width:min(480px,100%);padding:24px;box-sizing:border-box;border-radius:var(--copper-radius-card);background:var(--copper-surface);box-shadow:var(--copper-shadow-card);color:var(--copper-text);outline:none;}h2{display:flex;align-items:center;gap:10px;font-size:18px;}p{line-height:1.6;}footer{display:flex;justify-content:flex-end;gap:10px;}button{border:0;padding:10px 14px;border-radius:var(--copper-radius-control);background:var(--copper-hover);color:inherit;cursor:pointer;}button:last-child{background:var(--copper-accent);color:var(--copper-on-accent,#fff);}button:disabled{opacity:.6;}button:focus-visible{outline:2px solid var(--copper-accent);}.spin{animation:spin 1s linear infinite;}@keyframes spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spin{animation:none}}</style>
